UPDATE companies SET description='Greene Textile Inc. operates from Montebello, California, in the heart of Southern California''s textile corridor. The company was founded in 2001 by two brothers who had relocated from New York to California in the 1980s and spent two decades mastering yarn sourcing, knitting mechanics, and dye house operations before launching their own venture. They began in a modest office above a knitting mill and later expanded to a facility on Telegraph Road that now houses a showroom, warehouse, and operations.

The firm specializes in knit-to-order fabric production, offering a library of more than 4,000 styles developed primarily in cotton. Its capabilities span yarn sourcing, knitting, and both piece and garment dyeing, allowing customers to specify custom constructions, colors, and finishes.

Greene Textile serves clothing brands and small apparel businesses that need flexible minimums.

The founders emphasize a family-oriented culture rooted in treating employees and partners like family, a philosophy they trace to their early years in the local textile community.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Yarn sourcing", "Knit fabric manufacturing", "Piece dyeing", "Garment dyeing", "Custom knit development", "In-stock fabric program"], "industries": ["Apparel", "Clothing brands", "Small business apparel", "Fashion"], "materials": ["Cotton"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 2001 -> /about", "Two brothers relocated from New York in 1980s -> /about", "Started in small office above knitting mill -> /about", "Expanded to Telegraph Road Montebello facility with showroom, warehouse, operations -> /about", "Knit to order production -> db", "Library of over 4,000 styles using cotton -> db", "In-stock fabrics with low MOQs -> db", "Garment dyeing and piece dyeing -> db", "Serves clothing brands and small businesses -> db", "Family-oriented culture -> /about", "Domestic manufacturing in Southern California -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Founded in 2001, Greene Textile has proudly manufactured premium knit fabrics right here in Southern California.", "founded_year": "2001", "employee_count": "", "cage_code": "", "min_order": "Low minimum order quantities", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='greene-textile-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Gulf Side Fabricators, LLC operates from Broussard, Louisiana, on the Gulf Coast. The company was founded in October 2010 by industry veterans with over two decades of hands-on experience who were dissatisfied with prevailing quality standards.

The shop specializes in custom metal fabrication, including ASME-certified pressure vessels (U and R stamps), process piping to B31.3, and offshore/onshore piping systems. It runs a 24,000-square-foot campus that includes a dedicated carbon-steel facility and a separate exotic-alloy facility for stainless steel, super duplex, copper-nickel, and aluminum. Welding capabilities cover FCAW, GMAW, SMAW, and GTAW, supported by nesting software that the company says cuts material waste by up to 30 percent. In-house hydrostatic testing and full documentation packages are standard.

Gulf Side says it differentiates itself through a “Louisiana Pride” culture that invests in advanced technology, separate material streams to avoid cross-contamination, and a quality system built to the industry’s most demanding safety standards rather than minimum compliance.', certifications=ARRAY['ISO 9001','ASME U Stamp','ASME R Stamp','DNV 2.7-1','DNV 2.7-3','ASME B31.3']::text[], profile='{"capabilities": ["Custom metal fabrication", "ASME pressure vessel fabrication (U Stamp, R Stamp)", "Process piping fabrication (ASME B31.3)", "Offshore and onshore piping fabrication", "Exotic alloy fabrication (stainless steel, super duplex, copper nickel, aluminum)", "Welding: FCAW, GMAW, SMAW, GTAW", "Hydrostatic testing", "Non-destructive examination", "Nesting software for material optimization", "Complete testing and documentation"], "industries": ["Offshore oil and gas", "Marine", "Petrochemical", "Process piping", "Industrial fabrication"], "materials": ["Carbon steel", "Stainless steel", "Super duplex", "Copper nickel", "Aluminum"], "equipment": ["Fabrication machinery", "Nesting software"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Nesting software that reduces material waste by up to 30%", "Separate exotic-alloy facility prevents cross-contamination", "ASME U and R stamp pressure-vessel certifications", "DNV 2.7-1 and 2.7-3 offshore certifications", "Strategic Gulf Coast location with deep industry connections"], "facts_used": ["Founded October 2010 -> /about-us", "Headquarters Broussard, Louisiana -> db", "24,000 sq ft facility (2022) -> /about-us", "ASME U and R stamp certifications -> /about-us", "DNV 2.7-1 and 2.7-3 certifications -> /about-us", "ISO 9001 certification (2012) -> /about-us", "B31.3 process piping expertise -> /about-us", "Exotic alloy facility for stainless steel, super duplex, copper nickel, aluminum -> /about-us", "Welding processes FCAW, GMAW, SMAW, GTAW -> /", "Nesting software reduces waste up to 30% -> /", "Strategic Gulf Coast location -> /", "Offshore and onshore piping fabrication -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Gulf Side Fabricators emerged in October 2010... we engineer solutions... custom fabrication", "founded_year": "2010", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='gulfside-fabricators' AND approved AND profile IS NULL;
UPDATE companies SET description='Gusti Restaurant Equipment operates from a 30,000-square-foot showroom and warehouse on Dabney Road in Richmond, Virginia.

The company stocks and sells new restaurant equipment, furniture, smallwares, and outdoor cooking gear from multiple manufacturers. Its inventory spans front-of-house and back-of-house needs, including multi-compartment sinks, cooking lines, refrigeration, and tabletop items. The large facility allows walk-in shopping for both trade buyers and the general public.

