UPDATE companies SET description='Hinrichs Fine Woods originated in 1993 in Roca, Nebraska, with the goal of producing higher-quality cabinetry than competitors. The company began by building custom cabinets and furniture using solid wood, along with antique furniture restoration and repair, emphasizing wood joinery over mechanical fasteners and applying four coats of finish where others used three.

Today the shop operates from a 2,400-square-foot facility where it produces custom kitchen cabinets, bookcases, entertainment centers, bath cabinets, and other solid-wood furniture. All pieces feature inset, flush doors and drawers in traditional styles such as Mission, Shaker, and beaded face frames, with dovetailed drawers and premium hinges and guides. The restoration service refinishes antiques by hand—avoiding chemical dipping—to preserve joints and grain, then applies four coats of finish inside and out.

The company serves homeowners and collectors seeking custom cabinetry and heirloom restoration, delivering pieces built to last generations. Hinrichs Fine Woods differentiates itself by exceeding customer expectations through superior materials and craftsmanship—using wood joints instead of screws and nails, hand-stripping finishes, and applying four coats of finish inside and out.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom cabinetry", "Furniture restoration", "Antique restoration", "Custom kitchen cabinets", "Bookcase construction", "Entertainment center construction", "Bath cabinet construction", "Solid wood furniture making", "Inset flush door and drawer fabrication", "Dovetail joinery", "Beaded face frame construction", "Mission style cabinetry", "Shaker style cabinetry", "Hand refinishing", "Finish application (four coats)"], "industries": [], "materials": ["Solid wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Four coats of finish applied inside and out", "Hand-stripping of old finishes without chemical dipping", "Wood joinery used in place of screws and nails", "Dovetailed drawer construction", "Custom inset, flush doors and drawers"], "facts_used": ["Founded in 1993 -> /about", "2,400 square foot facility -> /about", "Custom cabinetry and furniture restoration -> /about", "Inset, flush doors and drawers -> /", "Dovetailed drawers -> /", "Mission, Shaker, beaded face frames -> /", "Four coats of finish inside and out -> /about", "Hand refinishing without chemical dipping -> /about", "Wood joinery instead of screws and nails -> /about", "Headquarters in Roca, Nebraska -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "building custom cabinets and furniture using solid wood", "founded_year": "1993", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() W