UPDATE companies SET description='House of Alpine operates from Englewood, Colorado, a suburb of Denver. The company was founded by Mike Rudd, an industrial designer who previously built and expanded a furniture business in Sydney, Australia, before moving to the United States. Rudd serves as lead industrial designer and furniture maker, guiding the company’s creative direction.

The workshop designs and manufactures custom solid wood furniture, managing the process from hand selection of each lumber piece through artisan craftsmanship to final finishing. The focus is on elegant, sophisticated, and simplistic furnishings intended to last for generations. No facility size or employee count is disclosed, but the company describes itself as a small local provider.

The company positions itself as a local source for bespoke pieces, though no specific commercial or industrial clients are named.

Rudd’s background in industrial design and his passion for nature and the outdoors inform the company’s aesthetic, which he describes as honest, passionate, and authentic. The stated goal is to create furniture that endures a lifetime, reflecting the surrounding Rocky Mountain environment.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Solid wood furniture manufacturing", "Hand selection of lumber", "Artisan woodworking"], "industries": [], "materials": ["Solid wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Hand selection of every piece of wood", "Artisan craftsmanship on every project", "Industrial design expertise", "Furniture made to last a lifetime"], "facts_used": ["Headquarters in Englewood, Colorado -> db", "Founded by Mike Rudd, industrial designer turned furniture maker -> /about", "Previously grew furniture business in Sydney, Australia -> /about", "Designs and produces custom solid wood furniture -> /", "Hand selection of every piece of wood -> /", "Artisan craftsmanship on every project -> /", "Local provider of high quality, affordable custom furniture -> /", "Emphasis on honest, passionate, authentic furniture made to last a lifetime -> /about", "Small business -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "custom furniture company committed to designing and producing elegant, solid wood furniture", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Small business"]}'::jsonb, updated_at=now() WHERE slug='house-of-alpine-handcrafted-custom-wood-furniture' AND approved AND profile IS NULL;
UPDATE companies SET description='House of Sharp operates from a 4,000-square-foot facility in Mulvane, Kansas, just outside Wichita. The company was founded in January 2018 by co-owners Ernest Sharp and Rose Hansen, who started with a CNC plasma table built in the basement of a rental house. Sharp, a college student at the time, and Hansen, looking to leave a 9-to-5 job, combined technical fabrication skills with creative design to launch the business.

The shop provides turnkey custom metal fabrication, handling design through production in-house. The team includes a graphic designer, CAD designer, mechanical engineer, and skilled fabricators working with a fully equipped metal shop. Capabilities span CNC plasma cutting, welding, and assembly, producing items such as custom signs, railings, furniture, interior accents, gates, fences, bike racks, awards, and decorative screens. The facility also includes a showroom and retail storefront.

House of Sharp serves both commercial clients and individual customers across Kansas.

The founders emphasize a business driven by passion, talent, creativity, and fun, aiming to offer a premiere customer experience and craftsmanship that exceeds expectations. Their differentiator lies in the integration of design, engineering, and fabrication under one roof, allowing them to take projects from concept to finished product without outsourcing.', certifications=ARRAY[]::text[], profile='{"capabilities": ["CNC plasma cutting", "Metal fabrication", "Welding", "Graphic design", "CAD design", "Mechanical engineering", "Custom metal signage", "Custom metal railings", "Custom metal furniture", "Custom interior accents", "Custom gates and fences", "Custom bike racks", "Custom awards", "Custom screens"], "industries": [], "materials": [], "equipment": ["CNC plasma table"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["In-house graphic design, CAD, and mechanical engineering", "Fully-outfitted metal shop with CNC plasma cutting", "Turnkey custom fabrication from concept to finished product", "4,000 sq ft facility with showroom and retail space", "Small business focused on passion and creativity"], "facts_used": ["Founded January 2018 by Ernest Sharp and Rose Hansen -> /about-us", "4,000 sq ft shop with showroom and retail storefront -> /about-us", "In-house graphic designer, CAD designer, mechanical engineer, and fabrication team -> /", "Custom metal fabrication including signs, railings, furniture, gates, bike racks, awards, screens -> /", "Serves Kansas businesses and the public -> /", "Small business -> /", "CNC plasma table built in basement -> /about-us"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "custom turnkey metal fabrication solutions", "founded_year": "2018", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Small business"]}'::jsonb, updated_at=now() WHERE slug='house-of-sharp' AND approved AND profile IS NULL;
UPDATE companies SET description='Howard Foods Inc. operates from Danvers, Massachusetts, where its sales office has been based since 1990. The company traces its origins to the early 1890s when John F. Howard and his wife Margaret began producing relishes in the barn behind their Bradford home, drawing on recipes developed for Howard''s Haverhill hotels. The business was formally incorporated after Howard sold it to Arthur D. Dickson in 1924, and a year later merged with the C.E. Chapin Company (founded 1872) to consolidate production in a Haverhill plant. Subsequent owners included ERE Industries, John Labatt Limited, and Campbell Soup Company (Canada) before the current ownership group acquired the brand in 1990.

The firm manufactures a line of shelf-stable condiments that includes Sweet Pepper Relish, Hot Pepper Relish, Green Tomato Piccalilli, Ham Glaze, and Garlic and Onion Seasoning Juices. Production follows the original late-19th-century formulations, which the company says have never been altered.

Howard Foods serves retail grocery, foodservice, and e-commerce channels primarily in the New England region.

The brand''s differentiation rests on its uninterrupted recipe heritage — the 1900 Grand Prix award in Paris for purity and quality is still cited — and on a positioning that emphasizes natural ingredients, simplicity, and a "homemade" taste maintained across more than 130 years.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Gourmet condiment manufacturing", "Relish production (sweet pepper, hot pepper)", "Piccalilli production", "Ham glaze production", "Seasoning juice production (garlic, onion)", "Recipe formulation and preservation", "Retail packaging and labeling", "Foodservice packaging", "E-commerce fulfillment"], "industries": ["Food and beverage manufacturing", "Condiments and sauces", "Retail grocery", "Foodservice distribution", "E-commerce / direct-to-consumer"], "materials": ["Red bell peppers", "Green bell peppers", "Green tomatoes", "Onions", "Brown sugar", "Cider vinegar", "Spice blends", "Maple syrup"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Recipes unchanged since the late 1800s", "Grand Prix winner at 1900 Paris International Exhibition", "#1 Sweet Pepper Relish in America", "Over 130 years of continuous production", "Natural ingredients with no recipe alterations"], "facts_used": ["Company name: Howard Foods Inc -> db", "HQ city: Danvers, Massachusetts -> db", "Founded in early 1890s by John F. Howard and Margaret Howard in Bradford, MA -> about-us", "Incorporated 1924 after sale to Arthur D. Dickson -> about-us", "Merged with C.E. Chapin Company (founded 1872) in 1926 -> about-us", "Subsequent owners: ERE Industries, John Labatt Limited, Campbell Soup Company (Canada) -> about-us", "Current owners purchased in 1990, moved sales office to Danvers, MA -> about-us", "Products: Sweet Pepper Relish, Hot Pepper Relish, Green Tomato Piccalilli, Ham Glaze, Garlic Seasoning Juice, Onion Seasoning Juice -> about-us", "Recipes unchanged since origin -> about-us", "Won Grand Prix at International Exhibition in Paris 1900 -> about-us, /", "Sweet Pepper Relish is #1 in America -> /, about-us", "Serving customers for over 130 years -> /", "Since the 1800s / early 1800s -> /", "Sold through New England grocery stores and online -> /", "Natural ingredients, simplicity -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Our Sweet Pepper Relish is made with the plumpest, sweetest red bell peppers, while our Hot Pepper relish is made with red bell peppers and green peppers.", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='howard-foods-inc' AND approved AND profile IS NULL;
